// Some portions generated by Codex
package org.eclipse.rdf4j.sail.shacl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryParseOptions.GraphAlgebraMode;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.DefaultEvaluationStrategyFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.eclipse.rdf4j.sail.shacl.wrapper.data.VerySimpleRdfsBackwardsChainingConnection;
import org.junit.jupiter.api.Test;

class ShaclGraphAlgebraCapabilityTest {

	@Test
	void shaclPreparationUsesTheUnderlyingGraphEvaluator() {
		SailRepository repository = new SailRepository(new ShaclSail(new MemoryStore()));
		try (var connection = repository.getConnection()) {
			var vf = repository.getValueFactory();
			var graphName = vf.createIRI("urn:data");
			connection.add(vf.createIRI("urn:s"), vf.createIRI("urn:p"), vf.createLiteral("value"), graphName);
			var query = connection.prepareTupleQuery(QueryLanguage.SPARQL, "SELECT ?g WHERE { GRAPH ?g {} }", null);
			assertEquals(GraphAlgebraMode.GRAPH, query.getParsedQuery().getParseOptions().graphAlgebraMode());
			try (var rows = query.evaluate()) {
				assertTrue(rows.hasNext());
				assertEquals(graphName, rows.next().getValue("g"));
				assertFalse(rows.hasNext());
			}
			connection.prepareUpdate("INSERT { <urn:new> <urn:p> 1 } WHERE { GRAPH <urn:missing> {} }").execute();
			assertFalse(connection.hasStatement(vf.createIRI("urn:new"), null, null, false));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void customUnderlyingEvaluatorRetainsLegacyDefault() {
		MemoryStore base = new MemoryStore();
		base.setEvaluationStrategyFactory(new DefaultEvaluationStrategyFactory() {
		});
		SailRepository repository = new SailRepository(new ShaclSail(base));
		try (var connection = repository.getConnection()) {
			var query = connection.prepareTupleQuery(QueryLanguage.SPARQL, "SELECT ?g WHERE { GRAPH ?g {} }", null);
			assertEquals(GraphAlgebraMode.LEGACY, query.getParsedQuery().getParseOptions().graphAlgebraMode());
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void backwardChainingWrapperDelegatesGraphCapabilityWithoutOptingInSubclasses() {
		MemoryStore base = new MemoryStore();
		base.init();
		try (var delegate = base.getConnection()) {
			assertTrue(new VerySimpleRdfsBackwardsChainingConnection(delegate, null).supportsGraphAlgebra());
			assertFalse(new VerySimpleRdfsBackwardsChainingConnection(delegate, null) {
			}.supportsGraphAlgebra());
			ShaclSail shacl = new ShaclSail(base);
			assertFalse(new ShaclSailConnection(shacl, delegate, null) {
			}.supportsGraphAlgebra());
		} finally {
			base.shutDown();
		}
	}
}
